# -*- coding: utf-8 -*-
# (speaker, italian, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
MT, C, SB = "Matteo", "Chiara", "Sandro"
D = [
("#", "Scena 1 — Lunedì 27 gennaio, ore 8.15. Superstrada Firenze–Pisa–Livorno.", "장면 1 — 1월 27일 월요일 오전 8시 15분. 피렌체–피사–리보르노 간선도로."),
(None, "Nebbia sulla piana dell'Arno. Matteo guida la vecchia Panda del laboratorio; Chiara tiene sulle ginocchia una cartella di disegni e un metro da sarta.", "아르노 평야에 안개가 깔려 있다. 마테오가 공방의 낡은 판다를 몰고, 키아라는 무릎 위에 그림 폴더와 줄자를 올려놓았다."),
(C, "Rallenta, Matteo. Non siamo su un'autostrada coreana.", "속도 줄여, 마테오. 여긴 한국 고속도로가 아니야."),
(MT, "A Seul in macchina non ci andavo mai. Metropolitana. Qui invece la FI-PI-LI è un rally.", "서울에선 차를 아예 안 탔어. 지하철이었지. 그런데 여기 피필리는 완전 랠리네."),
(C, "Allora guida come uno di qui: piano e brontolando. Gli hai telefonato, a Bini?", "그럼 여기 사람처럼 몰아. 천천히, 투덜대면서. 비니한테 전화는 했어?"),
(MT, "Venerdì. Mi ha risposto: «Venga lunedì alle nove. Ma non dopo le nove e un quarto, che poi vado ai bottali.»", "금요일에. '월요일 9시에 오세요. 9시 15분 넘으면 안 됩니다. 그다음엔 통 보러 가야 하니까'래."),
(C, "Sta tutto il giorno in conceria. Renzo dice che ha la testa dura.", "하루 종일 무두질 공장에 있대. 렌초 말로는 고집이 세고."),
(MT, "L'ho capito al telefono. Gli ho detto «la chiamo per una collaborazione strategica» e lui ha riattaccato.", "전화로 알았어. '전략적 협업 건으로 연락드렸습니다'라고 했더니 끊어 버리더라."),
(C, "Ha riattaccato?", "끊었다고?"),
(MT, "Ha detto: «Qui si vende cuoio, mica strategie.» E giù. Ho dovuto richiamarlo.", "'여긴 가죽을 팔지, 전략을 파는 데가 아닙니다' 하고 뚝. 다시 걸어야 했어."),
(C, "(ride) Te l'avevo detto: presentati come il nipote di Ugo, non come quello di Londra.", "(웃으며) 내가 말했지. 런던에서 온 사람 말고 우고의 손자라고 소개하라고."),
(MT, "Infatti la seconda volta ho detto solo: «Sono Matteo, il nipote di Ugo Corsini. Mia sorella cerca un vitello tabacco.» E ha detto subito di sì.", "그래서 두 번째엔 그냥 '우고 코르시니의 손자 마테오입니다. 누나가 담뱃잎 색 송아지 가죽을 찾습니다'라고만 했지. 그랬더니 바로 오라더라."),
(C, "Vedi? Le parole giuste.", "봐. 맞는 말을 하면 되잖아."),
(MT, "Senti, prima di arrivare: cosa ti serve esattamente? Così so cosa negoziare.", "도착하기 전에 말해 줘. 정확히 뭐가 필요해? 뭘 협상할지 알아야지."),
(C, "Vitello conciato al vegetale, pieno fiore, spessore uno e quattro, uno e sei. Colore tabacco, ma tinto in botte, non spruzzato sopra. E per i fondi un uno e otto.", "식물성 무두질한 송아지 가죽, 풀그레인, 두께 1.4에서 1.6. 담뱃잎 색인데, 위에 뿌린 게 아니라 통에서 염색한 거. 그리고 바닥용은 1.8."),
(MT, "Pieno fiore?", "풀그레인?"),
(C, "La parte esterna della pelle, quella intera, non levigata. È la più bella e la più cara. Se ti propone «fiore corretto», dici di no.", "가죽 바깥쪽 면을 갈지 않고 통째로 쓴 거야. 제일 예쁘고 제일 비싸. 그 사람이 '수정 그레인'을 권하면 안 된다고 해."),
(MT, "«Fiore corretto» no. Me lo segno. E quante pelli?", "'수정 그레인'은 안 된다. 적어 둘게. 그럼 몇 장?"),
(C, "Per tutta la prima linea, una quarantina. Ma prima voglio vederle e toccarle.", "첫 라인 전체에 마흔 장쯤. 하지만 먼저 보고 만져 봐야 해."),
(MT, "Una quarantina... Filippo mi ha detto: niente impegni sopra i cinquemila euro senza la sua firma.", "마흔 장이라... 형이 그랬어. 5천 유로 넘는 약속은 자기 서명 없이는 하지 말라고."),
(C, "Allora la conceria ti piacerà poco. Il cuoio buono costa.", "그럼 무두질 공장이 별로 마음에 안 들 거야. 좋은 가죽은 비싸거든."),

("#", "Scena 2 — Ore 9. Conceria Bini, Santa Croce sull'Arno.", "장면 2 — 오전 9시. 산타크로체 술라르노, 비니 무두질 공장."),
(None, "Un capannone basso tra altri capannoni. Un odore acre di corteccia bagnata e di pelle. Grandi cilindri di legno girano lentamente, con un rumore sordo d'acqua. Sandro Bini, sessantaquattro anni, stivali di gomma e grembiule cerato, li aspetta sulla porta.", "다른 창고들 사이의 낮은 창고. 젖은 나무껍질과 가죽의 시큼한 냄새. 커다란 나무 원통들이 둔탁한 물소리를 내며 천천히 돈다. 예순넷의 산드로 비니가 고무장화에 방수 앞치마 차림으로 문 앞에서 기다린다."),
(SB, "Buongiorno. Siete i Corsini? Puntuali. Il nonno arrivava sempre in anticipo, con la Vespa, e voleva vedere tutto.", "안녕하십니까. 코르시니네 분들? 시간 딱 맞추셨네. 할아버지는 늘 일찍 왔지. 베스파를 타고. 그리고 전부 다 보고 싶어 했어."),
(MT, "Buongiorno, signor Bini. Grazie di riceverci. Sono Matteo. E questa è mia sorella Chiara, la stilista.", "안녕하세요, 비니 사장님. 맞아 주셔서 감사합니다. 마테오입니다. 그리고 이쪽은 디자이너인 저희 누나 키아라예요."),
(SB, "Lei è la bimba che disegnava sui ritagli? Me l'ha detto Renzo, al telefono. M'ha chiamato ieri sera.", "당신이 자투리에 그림 그리던 그 꼬마요? 렌초가 전화로 그러더군. 어젯밤에 전화했어요."),
(C, "Renzo l'ha chiamata?", "렌초가 전화를 했다고요?"),
(SB, "E m'ha detto: «Trattali bene, ma un fargli sconti.» (ride) Venite, vi faccio vedere. Ma attenti dove mettete i piedi: qui per terra c'è più acqua che in Arno.", "그러고는 '잘 대해 주되 깎아 주지는 마' 하더군. (웃으며) 이리 와요, 보여 드릴게. 근데 발밑 조심해요. 여기 바닥엔 아르노강보다 물이 더 많으니까."),
(MT, "Che odore... È fortissimo.", "냄새가... 엄청 세네요."),
(SB, "È l'odore del lavoro. Chi lo sente la prima volta storce il naso. Chi ci nasce, se va in città, la notte un dorme.", "일하는 냄새요. 처음 맡는 사람은 코를 찡그리지. 여기서 태어난 사람은 도시에 가면 밤에 잠을 못 자요."),
(MT, "Da dove si comincia?", "어디서부터 시작하나요?"),
(SB, "Dalla pelle grezza. Arriva salata, dai macelli, soprattutto francesi e olandesi. Il sale la conserva durante il viaggio.", "생가죽부터요. 도축장에서 소금에 절여 와요. 주로 프랑스, 네덜란드에서. 운송하는 동안 소금이 보존해 주지."),
(MT, "E poi?", "그다음은요?"),
(SB, "Poi viene messa a bagno per togliere il sale e farle riprendere l'acqua: è il rinverdimento. Poi il calcinaio, per togliere il pelo. Poi la scarnatura: si leva il grasso e la carne dalla parte di sotto.", "그다음엔 물에 담가서 소금을 빼고 다시 물을 머금게 해요. 그게 침지 공정. 그다음 석회 처리로 털을 빼고. 그다음 육면 제거, 안쪽의 기름이랑 살점을 긁어내지."),
(C, "E la spaccatura? Per lo spessore?", "그럼 분할은요? 두께를 맞추는 거요."),
(SB, "Brava. Con la spaccatrice si divide la pelle in due: sopra il fiore, sotto la crosta. Il fiore va a voi. La crosta va a chi fa le scarpe economiche.", "잘 아시네. 분할기로 가죽을 둘로 나눠요. 위가 그레인, 아래가 스플릿. 그레인은 당신들한테 가고, 스플릿은 싼 구두 만드는 데로 가지."),
(MT, "E qui arrivano i tannini?", "여기서 타닌이 들어가나요?"),
(SB, "Qui arriva la concia. Questi sono i bottali. (indica i grandi cilindri di legno) Dentro ci sono le pelli e i tannini.", "여기서 무두질이 시작되지. 이게 보탈레, 무두질 통이에요. (커다란 나무 원통을 가리키며) 안에 가죽이랑 타닌이 들어 있어요."),
(MT, "Tannini di cosa? Di vino?", "무슨 타닌이요? 와인이요?"),
(SB, "(ride) Di vino! Sentilo, il londinese. Tannini di piante: castagno, mimosa, quebracho. Estratti dalla corteccia e dal legno. Come una volta, solo che ora si misura tutto.", "(웃으며) 와인이래! 들어 봐, 런던 양반. 식물 타닌이에요. 밤나무, 미모사, 케브라초. 나무껍질이랑 목재에서 뽑은 거지. 옛날 방식 그대로인데, 다만 지금은 전부 재서 하죠."),
(C, "Quanto restano nei bottali?", "통 안에 얼마나 있어요?"),
(SB, "Dipende dalla ricetta. Qui da noi prima qualche giorno in vasca, a bagno lento, poi nei bottali. In tutto, dalla grezza alla finita, ci vogliono quasi quaranta giorni.", "레시피에 따라 다르지. 우린 먼저 며칠 동안 수조에서 천천히 담갔다가, 그다음 통으로 옮겨요. 생가죽에서 완성까지 다 합치면 거의 40일 걸립니다."),
(MT, "Quaranta giorni? E una concia al cromo quanto ci mette?", "40일이요? 크롬 무두질은 얼마나 걸려요?"),
(SB, "Un giorno, due. Per questo costa meno. Ma il cromo fa una pelle che resta com'è. Il vegetale invece vive: cambia colore, prende la forma, invecchia.", "하루, 이틀. 그래서 싸지. 그런데 크롬은 처음 그대로 남는 가죽을 만들어요. 식물성은 살아 있지. 색이 변하고, 모양을 잡고, 나이를 먹어요."),
(C, "È quello che diceva Renzo. Invecchia bene.", "렌초가 한 말이네요. 나이를 잘 먹는다고."),
(SB, "Renzo dice cose giuste da cinquant'anni. Venite di qua: l'asciugatura.", "렌초는 50년째 옳은 소리만 하지. 이쪽으로 와요. 건조장."),
(None, "Un lungo locale arieggiato. Centinaia di pelli pendono da travi di legno, come lenzuola stese ad asciugare.", "바람이 잘 통하는 긴 공간. 수백 장의 가죽이 빨래처럼 나무 들보에 걸려 마르고 있다."),
(MT, "Le pelli vengono appese così, all'aria?", "가죽을 이렇게 공기 중에 매달아 두는 거예요?"),
(SB, "All'aria, piano piano, senza forzare. Se le asciughi in fretta, si induriscono e si spaccano. Il cuoio buono un ha fretta.", "공기 중에, 천천히, 억지로 하지 않고. 서둘러 말리면 딱딱해지고 갈라져요. 좋은 가죽은 서두르지 않아."),
(MT, "Questa frase la conosco. Me la ripete mia sorella da una settimana.", "그 말 아는데요. 누나가 일주일째 저한테 하는 말이에요."),
(C, "Perché è vera.", "사실이니까."),
(SB, "Poi viene la rifinitura: si rasa la pelle allo spessore giusto, si ingrassa, si tinge in botte, si stira. Alla fine si lucida. Alcune a mano, con il cilindro di vetro.", "그다음이 마감이에요. 두께에 맞게 깎고, 기름을 먹이고, 통에서 염색하고, 다림질하고. 마지막에 광을 내지. 어떤 건 손으로, 유리 원통으로."),
(C, "(tocca una pelle color tabacco appesa) Questa. Questa è lei.", "(걸려 있는 담뱃잎 색 가죽을 만지며) 이거. 바로 이거예요."),
(SB, "Ha l'occhio di suo nonno, signora. È il nostro tabacco, tinto in botte. Pieno fiore, uno e cinque.", "할아버지 눈을 닮으셨네. 우리 담뱃잎 색이에요. 통 염색, 풀그레인, 1.5밀리."),
(C, "Matteo, tocca.", "마테오, 만져 봐."),
(MT, "(tocca) È... calda. Sembra viva.", "(만져 보며) 따뜻해... 살아 있는 것 같아."),
(SB, "Perché lo è. Venite in ufficio, che qui coi bottali un si sente nulla.", "살아 있으니까. 사무실로 갑시다. 여긴 통 소리 때문에 아무것도 안 들려."),

("#", "Scena 3 — Ore 10. L'ufficio della conceria.", "장면 3 — 오전 10시. 무두질 공장 사무실."),
(None, "Un ufficio piccolo, con un calendario di un fornitore di prodotti chimici e campioni di cuoio inchiodati alla parete. Sandro prepara la moka su un fornellino elettrico.", "작은 사무실. 화학약품 납품업체 달력과 벽에 못 박힌 가죽 견본들. 산드로가 전기 버너에 모카포트를 올린다."),
(SB, "Un caffè? È della moka, mica della macchinetta di Londra.", "커피 한잔? 모카포트 커피예요. 런던 머신 커피가 아니고."),
(MT, "Volentieri. Signor Bini, parliamo di numeri?", "좋습니다. 비니 사장님, 숫자 얘기 할까요?"),
(SB, "Parliamo di numeri. Ma intanto dammi del tu. Al nipote di Ugo il «lei» un glielo do.", "숫자 얘기 합시다. 근데 그 전에 말 편하게 해. 우고 손자한테 존댓말은 안 쓸 거니까."),
(MT, "D'accordo. Allora anch'io ti do del tu, Sandro?", "좋아요. 그럼 저도 말 편하게 해도 될까요, 산드로?"),
(SB, "Se ce la fai. I giovani d'oggi, coi più vecchi, un ce la fanno mai.", "할 수 있으면. 요즘 젊은 사람들은 나이 많은 사람한테 그걸 못 하더라고."),
(C, "Io continuo con il Lei, se non le dispiace. Mi viene più naturale.", "저는 계속 존댓말 쓸게요, 괜찮으시다면. 그게 더 편해서요."),
(SB, "Lei faccia come vuole. Le stiliste son così: rispettose coi vecchi e cattive con le pelli.", "편하실 대로. 디자이너들은 다 그래요. 늙은이한테는 공손하고 가죽한테는 깐깐하고."),
(MT, "Il vitello tabacco. Quanto costa?", "담뱃잎 색 송아지 가죽, 얼마예요?"),
(SB, "Sei euro e venti al piede quadro. Pieno fiore, prima scelta.", "평방피트당 6유로 20센트. 풀그레인, 1등급."),
(MT, "Al piede quadro... Non al metro quadro?", "평방피트당이요? 제곱미터가 아니라?"),
(SB, "Nel cuoio si conta in piedi quadri. Un piede è più o meno nove decimetri quadri. Una pelle di vitello fa venti, venticinque piedi.", "가죽은 평방피트로 셉니다. 1피트가 대략 9제곱데시미터쯤. 송아지 가죽 한 장이 20에서 25피트쯤 나와요."),
(MT, "Quindi una pelle costa più o meno... centoquaranta euro?", "그럼 한 장에 대략... 140유로요?"),
(SB, "Più o meno. Dipende da quant'è grande. Si paga la misura vera, quella della macchina.", "대략. 크기에 따라 달라요. 기계로 잰 실제 면적대로 받지."),
(C, "L'anno scorso non era sei e venti. Era intorno ai cinque e sessanta, mi pare.", "작년엔 6유로 20이 아니었는데요. 5유로 60쯤이었던 것 같은데."),
(SB, "Brava, se lo ricorda. È salito tutto: le pelli grezze, i tannini, l'energia per i bottali, la depurazione dell'acqua. Più dell'undici per cento in un anno.", "잘 기억하시네. 다 올랐어요. 생가죽, 타닌, 통 돌리는 전기, 폐수 처리. 1년 새 11퍼센트 넘게."),
(MT, "Capisco. E il minimo d'ordine?", "알겠습니다. 최소 주문량은요?"),
(SB, "Cinquanta pelli per colore. Sotto le cinquanta, la botte un la riempio e ci rimetto.", "색상별 50장. 50장 아래면 통을 못 채워서 내가 손해야."),
(MT, "Cinquanta pelli sono mille, mille e cento piedi. Più di seimila euro.", "50장이면 1,000에서 1,100피트. 6천 유로가 넘네요."),
(SB, "Sei bravo coi conti, ragazzo. E il pagamento: metà all'ordine, metà alla consegna.", "계산 빠르네, 젊은이. 그리고 결제는 주문할 때 절반, 납품할 때 절반."),
(MT, "Metà all'ordine? Con la Maison lavorate a novanta giorni, credo.", "주문할 때 절반이요? 메종하고는 90일 조건으로 거래하시잖아요."),
(SB, "Con la Maison, sì. Ma la Maison la pelle me la paga lei, direttamente, e la sceglie lei. Voi Corsini da me un avete mai comprato niente a nome vostro. Per me siete nuovi.", "메종하곤 그렇지. 그런데 메종은 가죽값을 자기가 직접 내고, 고르는 것도 자기가 해. 당신들 코르시니는 자기 이름으로 나한테 뭘 산 적이 한 번도 없어. 나한텐 신규 거래처야."),
(C, "Nuovi? Il nonno comprava qui da trent'anni.", "신규요? 할아버지는 30년 동안 여기서 사셨는데요."),
(SB, "Il nonno comprava qui. Poi è arrivata la Maison, e il nome Corsini sulle mie fatture è sparito. Mi dispiace, signora, ma la memoria, nel cuoio, un vale come garanzia.", "할아버지는 여기서 샀지. 그러다 메종이 오고 내 송장에서 코르시니란 이름이 사라졌어요. 미안하지만, 이 바닥에선 추억이 보증이 되진 않아요."),
(MT, "È giusto. Allora proviamo un'altra strada. Possiamo fare meno di cinquanta, se teniamo il prezzo pieno?", "맞는 말씀이에요. 그럼 다른 길을 찾아보죠. 정가를 그대로 낸다면 50장보다 적게도 될까요?"),
(SB, "Quante?", "몇 장?"),
(MT, "Trenta pelli. Seicento piedi, più o meno. Per una prima linea di prova.", "30장. 대략 600피트요. 시범 라인 하나 만들 만큼."),
(SB, "Trenta... E la botte? La riempio a metà?", "30장이라... 그럼 통은? 반만 채우라고?"),
(C, "E se le prendiamo dal lotto che ha già appeso? Quello tabacco che ho toccato prima. Non deve tingere niente di nuovo.", "아까 제가 만진, 이미 걸려 있는 그 담뱃잎 색 로트에서 가져가면요? 새로 염색할 필요가 없잖아요."),
(SB, "(si gratta la testa) Quel lotto... è di un cliente tedesco che un s'è più fatto vivo. Di pelli ce ne sono trentotto.", "(머리를 긁으며) 그 로트는... 연락이 끊긴 독일 손님 거예요. 서른여덟 장 있지."),
(MT, "Allora ne prendiamo trenta. Subito. Dal lotto pronto.", "그럼 그중 서른 장을 가져갈게요. 지금 바로. 준비된 로트에서."),
(SB, "Pronto, pronto... Va rifinito. Rasatura e stiratura. Due settimane.", "준비됐다 해도... 마감은 해야 해요. 깎고 다림질하고. 2주."),
(C, "Due settimane va bene. E per i fondi, l'uno e otto?", "2주면 괜찮아요. 그럼 바닥용 1.8은요?"),
(SB, "Quello ce l'ho naturale, non tinto. Ve lo tingo a mano, a tampone. Dieci pelli, stesso prezzo.", "그건 염색 안 한 내추럴로 있어요. 손으로, 탐폰으로 염색해 드리지. 열 장, 같은 값에."),
(MT, "Quindi: trenta pelli tabacco più dieci naturali tinte a mano. Quaranta pelli, circa ottocento piedi, a sei e venti.", "그러니까 담뱃잎 색 서른 장에, 손으로 염색한 내추럴 열 장. 마흔 장, 약 800피트, 피트당 6유로 20."),
(SB, "Hai fatto i conti più in fretta di me.", "나보다 계산이 빠르구먼."),
(MT, "Fanno circa cinquemila euro. Possiamo fare un anticipo del trenta per cento, e il resto alla consegna?", "대략 5천 유로네요. 선금 30퍼센트, 나머지는 납품 때로 할 수 있을까요?"),
(SB, "Il cinquanta. Te l'ho detto.", "50. 말했잖아."),
(MT, "Il trenta, Sandro. In cambio, se la prima linea va bene, il prossimo ordine è di almeno duecento pelli. E da lì in poi, pagamento a sessanta giorni.", "30이요, 산드로. 대신 첫 라인이 잘되면 다음 주문은 최소 200장. 그리고 그때부터는 60일 결제로요."),
(SB, "Se va bene. E se va male?", "잘되면. 안 되면?"),
(MT, "Se va male, hai venduto trenta pelli di un tedesco sparito. Meglio di niente.", "안 되면 사라진 독일 손님 가죽 서른 장을 판 거죠. 아무것도 없는 것보단 낫잖아요."),
(C, "Matteo!", "마테오!"),
(SB, "(ride forte) No, no, ha ragione il bimbo. Mi garba. Ugo avrebbe detto la stessa cosa, però con più garbo.", "(크게 웃으며) 아니, 아니, 이 녀석 말이 맞아. 마음에 드네. 우고도 똑같은 말을 했을 거야. 좀 더 점잖게 했겠지만."),
(MT, "Allora facciamo il trenta?", "그럼 30으로 할까요?"),
(SB, "Il trenta. A patto che il bonifico arrivi entro venerdì. E che la signora venga lei a scegliere le pelli, una per una.", "30. 단, 금요일까지 송금이 들어오면. 그리고 이분이 직접 와서 가죽을 한 장 한 장 고른다면."),
(C, "Ci vengo volentieri. Anzi, ci tengo.", "기꺼이 올게요. 아니, 꼭 오고 싶어요."),
(SB, "E un'altra cosa. Sulle vostre etichette ci voglio il nome della conceria. «Cuoio conciato al vegetale, Conceria Bini, Santa Croce.»", "그리고 하나 더. 당신들 라벨에 우리 공장 이름을 넣어 줘요. '식물성 무두질 가죽, 비니 무두질 공장, 산타크로체.'"),
(MT, "Sulle etichette? Per chi compra a Seul?", "라벨에요? 서울에서 사는 사람을 위해서요?"),
(SB, "Per chi compra dappertutto. Tu vendi la borsa, io vendo il cuoio. Se il cliente sa da dove viene, si fida di più.", "어디서 사든 다. 넌 가방을 팔고 난 가죽을 팔지. 손님이 그게 어디서 왔는지 알면 더 믿어."),
(C, "Ha ragione. A Seul vogliono la storia. Ce l'ha detto anche Renzo, in un altro modo.", "맞는 말씀이에요. 서울에선 이야기를 원해요. 렌초도 다른 말로 그렇게 말했어요."),
(MT, "Va bene. Ne parlo con Filippo. Ma per me è un sì.", "좋아요. 형하고 얘기해 볼게요. 하지만 제 입장은 '예스'예요."),
(SB, "Con Filippo? Ah, il fratello grande. Quello che parla solo con Parigi.", "필리포랑? 아, 큰형. 파리하고만 얘기하는 그 사람."),
(MT, "Quello che firma i bonifici.", "송금에 서명하는 그 사람이요."),
(SB, "Allora parlaci bene. E di' a Renzo che un vi ho fatto sconti.", "그럼 잘 얘기해. 그리고 렌초한테 하나도 안 깎아 줬다고 전해."),
(C, "Glielo diremo. E grazie, signor Bini. Davvero.", "전할게요. 그리고 고맙습니다, 비니 사장님. 진심으로요."),
(SB, "Grazie a voi. Era tanto che un sentivo un Corsini chiedermi una pelle per una borsa sua.", "내가 고맙지. 코르시니 사람이 자기 가방 만들 가죽을 달라고 하는 걸 들은 게 정말 오랜만이야."),

("#", "Scena 4 — Ore 12. Di nuovo in macchina.", "장면 4 — 낮 12시. 다시 차 안."),
(None, "La nebbia si è alzata. Sul sedile posteriore, un campione di cuoio tabacco avvolto in carta velina.", "안개가 걷혔다. 뒷좌석에는 얇은 종이에 싼 담뱃잎 색 가죽 견본이 놓여 있다."),
(C, "Seicento... cioè ottocento piedi. Mi sento ricca.", "600... 아니, 800피트. 부자가 된 기분이야."),
(MT, "Ricca con cinquemila euro di cuoio e il trenta per cento di anticipo. Filippo mi ucciderà: il tetto era cinquemila.", "5천 유로어치 가죽에 선금 30퍼센트로 부자라. 형이 날 죽일 거야. 상한이 5천이었거든."),
(C, "Cinquemila meno qualcosa. E l'anticipo è millecinquecento. Il resto fra due settimane. Glielo spieghi bene.", "5천에서 조금 빠지잖아. 선금은 1,500이고. 나머지는 2주 뒤. 잘 설명해."),
(MT, "Glielo spiego coi numeri. Con quaranta pelli facciamo settanta, ottanta borse. Il cuoio pesa un terzo del costo di ogni borsa. Il resto sono mani.", "숫자로 설명할게. 마흔 장이면 가방 70~80개가 나와. 가방 하나 원가에서 가죽이 3분의 1이야. 나머지는 손이고."),
(C, "Le mani di Renzo e delle ragazze. Che a marzo, senza lavoro, starebbero a casa.", "렌초랑 여자들 손. 3월에 일이 없으면 집에 있게 될 손."),
(MT, "Questo lo dico a Filippo per primo.", "그 얘기부터 형한테 할 거야."),
(C, "Matteo... prima, quando hai detto «un tedesco sparito», ho avuto paura che ci cacciasse.", "마테오... 아까 '사라진 독일 손님' 얘기할 때, 그 사람이 우릴 쫓아낼까 봐 겁났어."),
(MT, "Anch'io. Ma a Seul ho imparato una cosa: quando il venditore ride, l'affare è fatto.", "나도. 그런데 서울에서 배운 게 하나 있어. 파는 사람이 웃으면 거래는 끝난 거야."),
(C, "E quando non ride?", "안 웃으면?"),
(MT, "Si torna il giorno dopo con un regalo.", "다음 날 선물 들고 다시 가는 거지."),
(C, "Allora venerdì, quando torno a scegliere le pelli, gli porto la schiacciata.", "그럼 금요일에 가죽 고르러 다시 갈 때 스키아차타를 사 가야겠다."),
(MT, "E il nome sull'etichetta? «Conceria Bini». Ti piace?", "라벨에 들어갈 이름은? '비니 무두질 공장'. 마음에 들어?"),
(C, "Mi piace. Una borsa con due nomi toscani. Per Seul è perfetta. Adesso manca solo il terzo nome: quello di Filippo, sotto il bonifico.", "마음에 들어. 토스카나 이름 두 개가 들어간 가방. 서울엔 딱이야. 이제 세 번째 이름만 남았네. 송금서 아래 필리포의 이름."),
]

